-- The unnormalised order export of examples/sql-flat, for MariaDB. Loaded by tools/check-usage.sh.
DROP TABLE IF EXISTS order_export;
CREATE TABLE order_export (line_id INT PRIMARY KEY, order_no VARCHAR(16) NOT NULL, order_date DATE NOT NULL, customer_name VARCHAR(80) NOT NULL, customer_email VARCHAR(120) NOT NULL, customer_city VARCHAR(60) NOT NULL, sku VARCHAR(16) NOT NULL, product_name VARCHAR(80) NOT NULL, category VARCHAR(40) NOT NULL, qty INT NOT NULL, unit_price DECIMAL(10,2) NOT NULL, tags VARCHAR(120) NOT NULL) DEFAULT CHARSET utf8mb4 COLLATE utf8mb4_general_ci;
